// Runs under the Hermes CLI (React Native's engine): the conformance suite, the compiler on the
// section-18 document, and the maths engine. Prints one result line per check.
import { checkCase, type ConfCase } from '../packages/core/src/conformance';
import { compile, MathsEngine, type PackSource } from '../packages/core/src/index';
// @ts-expect-error: generated by hermes-run.mjs
import data from './.hermes/data.json';

declare const print: (s: string) => void;
const out = (kind: string, v: unknown): void => print(`MKP-RESULT ${JSON.stringify({ kind, ...(v as object) })}`);

const d = data as { cases: ConfCase[]; packs: { label: string; files: Record<string, string> }[]; doc: { path: string; text: string; digest: string } };
const enc = new TextEncoder();

let failed = 0;
for (const c of d.cases) {
  let diffs: string[];
  try {
    diffs = checkCase(c);
  } catch (e) {
    diffs = [`threw: ${(e as Error).message}`];
  }
  if (diffs.length) failed++;
  out('case', { id: c.id, ok: !diffs.length, diffs: diffs.slice(0, 5) });
}

// the compiler itself, on the section-18 document
try {
  const packs: PackSource[] = d.packs.map((p) => ({ label: p.label, files: new Map(Object.entries(p.files).map(([k, v]) => [k, enc.encode(v)])) }));
  const c = compile({ packs });
  const b = c.document(d.doc.text, d.doc.path);
  out('compile', { ok: c.diags.ok && !!b && b.doc.digest === d.doc.digest, errors: c.diags.errors.length, digest: b?.doc.digest, defs: c.defs.size });
} catch (e) {
  out('compile', { ok: false, error: (e as Error).message });
}

MathsEngine.create().then(
  (m) => {
    const t0 = Date.now();
    const r = m.render('\\omega^n = 1', false);
    const s = m.speech('\\omega^n = 1', false);
    out('maths', { ok: !!r && r.svg.startsWith('<svg') && s === 'omega to the n-th power equals 1', ms: Date.now() - t0, speech: s });
    out('done', { failed, total: d.cases.length });
  },
  (e) => out('maths', { ok: false, error: String(e) }),
);
